const servers = $json.servers || []; 
const inputNode = $('[Trigger] Internal API Entry / [Trigger] Внутрішня точка входу API');

// 1. Беремо identifier, якщо він є
let target = String(inputNode.item.json.identifier || "").trim();
const query = String(inputNode.item.json.query || "").trim();
// Розбиваємо запит на частини одразу, бо нам знадобляться слова з нього
const parts = query.split(' ');

// 2. Якщо identifier пустий, пробуємо витягти назву з query
if (!target) {
  if (parts.length > 1) {
    // Беремо друге слово (назва сервера)
    target = parts[1].trim();
  } else {
    // Якщо там просто цифри (ID)
    const extractedId = query.match(/\d+/);
    if (extractedId) target = extractedId[0];
  }
}

// 3. Шукаємо збіг у списку від Hetzner
const match = servers.find(s => 
  String(s.id) === target || 
  s.public_net.ipv4.ip === target || 
  s.name === target
);

// Якщо сервер не знайдено
if (!match) {
  return { 
    error: 'Server not found', 
    searched_for: target,
    hint: "Убедитесь, что имя сервера введено правильно после команды" 
  };
}

// 4. Визначаємо дію для Action Router1
let action = "unknown";
const q = query.toLowerCase();

if (q.startsWith('reboot')) action = "reboot";
else if (q.startsWith('create_snapshot')) action = "create_image";
else if (q.startsWith('poweron')) action = "poweron";
else if (q.startsWith('poweroff')) action = "poweroff";
else if (q.startsWith('delete_server')) action = "delete_server";
else if (q.startsWith('change_type')) action = "change_type";
else if (q.startsWith('delete_snapshot')) action = "delete_snapshot";
else if (q.startsWith('list_snapshots')) action = "list_snapshots";

// 5. Витягуємо новий тип сервера з команди (наприклад: "change_type cvat-test15 cpx21")
let newType = "";
if (action === "change_type" && parts.length > 2) {
  newType = parts[2].trim();
}

// 6. Повертаємо всі зібрані дані
return { 
  id: match.id, 
  action: action, 
  name: match.name,
  newType: newType // Цей параметр тепер піде в HTTP Request для зміни типу
};

const action = $node["Route: Execute Task Logic / Route: Виконання логіки задачі"].json.action;
const name = $node["Script: Resource Identity Resolver / Скрипт: Визначення ідентифікатора ресурсу"].json.name;
return {
  success: true,
  message: `Команду [${action}] для сервера ${name} успішно відправлено в Hetzner.`,
  output: `Action ${action} executed`
};

