const serverName = $node["Script: Resource Identity Resolver / Скрипт: Визначення ідентифікатора ресурсу"].json.name;
const snapshotId = $json.action.resources[0].id;

return {
  success: true,
  message: `Створення Snapshot для сервера ${serverName} розпочато. ID задачі: ${snapshotId}.`,
  output: `Snapshot started for ${serverName}`
};

const images = $json.images || [];
const serverName = $('Script: Resource Identity Resolver / Скрипт: Визначення ідентифікатора ресурсу').first().json.name;
const serverId = String($('Script: Resource Identity Resolver / Скрипт: Визначення ідентифікатора ресурсу').first().json.id);

// 1. Шукаємо знімки: або за прив'язкою ID, або за назвою сервера в описі
const filteredImages = images.filter(i => 
  String(i.bound_to) === serverId || 
  (i.description && i.description.toLowerCase().includes(serverName.toLowerCase()))
);

// 2. Якщо для конкретного сервера порожньо, але запит був "а взагалі які є"
// віддаємо весь список (це допоможе Агенту не тупити)
const displayList = filteredImages.length > 0 ? filteredImages : images;

if (displayList.length === 0) {
  return {
    success: true,
    message: `📸 Наразі у вашому акаунті Hetzner не знайдено жодного знімка (snapshot).`,
    output: "No snapshots found at all"
  };
}

const list = displayList.map(i => `• **ID: ${i.id}** — ${i.description} (Сервер: ${i.bound_to || 'не вказано'})`).join('\n');

return {
  success: true,
  message: filteredImages.length > 0 
    ? `✅ Знайдені знімки для сервера ${serverName}:\n${list}`
    : `📸 Я не знайшов прямих знімків для ${serverName}, але ось список усіх знімків в акаунті:\n${list}`,
  output: list
};

const name = $('Script: Resource Identity Resolver / Скрипт: Визначення ідентифікатора ресурсу').first().json.name;
const newType = $('Script: Resource Identity Resolver / Скрипт: Визначення ідентифікатора ресурсу').first().json.newType;

return {
  success: true,
  message: `✅ Сервер ${name} успішно змінено на тариф ${newType}! Я самостійно вимкнув його, змінив тип і увімкнув назад. Сервер вже працює.`,
  output: `Type changed to ${newType}`
};

// Беремо назву сервера з попереднього кроку
const serverName = $('Script: Resource Identity Resolver / Скрипт: Визначення ідентифікатора ресурсу').first().json.name;

// Формуємо об'єкт відповіді
return {
  success: true,
  message: `Сервер ${serverName} успішно видалено з Hetzner та Cloudflare. Статус у таблиці оновлено на Deleted.`,
  // Цей параметр допоможе Агенту зрозуміти, що це кінець
  output: `Success: ${serverName} deleted`
};

const servers = $json.servers || [];

if (servers.length === 0) {
  return {
    success: true,
    output: "Наразі у вашому акаунті Hetzner немає активних серверів."
  };
}

// Формуємо короткий, читабельний маркдаун список для AI
const list = servers.map(s => 
  `• **ID:** ${s.id} | **Назва:** ${s.name} | **IP:** ${s.public_net?.ipv4?.ip || 'N/A'} | **Тип:** ${s.server_type?.name || 'N/A'} | **Статус:** ${s.status}`
).join('\n');

return {
  success: true,
  output: `Ось список серверів:\n\n${list}`
};
